## Client Side Routing
Vite does not support client side routing out of the box, but you can use **`react-router-dom`** or simply use Framework such as [**`nextjs`**](/framework-guides/nextjs), [**`react-router`**](/framework-guides/react-router), or [**`tanstack`**](/framework-guides/tanstack)

### React Router Dom
If you want to use **`react-router-dom`**, first install the package.

<CLI command='install' items='react-router-dom' />

### Client Provider
First create a **`src/components/client-provider.tsx`** file

```tsx title='client-provider.tsx'
import type { PropsWithChildren } from "react";
import { RouterProvider } from "react-aria-components";
import { useNavigate } from "react-router-dom";

export function ClientProvider({ children }: PropsWithChildren) {
  const navigate = useNavigate();
  return (
    <RouterProvider navigate={(to, options) => navigate(to, options)}>
      {children}
    </RouterProvider>
  );
}
```

Modify your **`App.tsx`** file or create new file such as **`router.tsx`**

```tsx title='router.tsx'
import { BrowserRouter, Routes, Route } from "react-router-dom"
import { Link } from "react-aria-components"
import Home from "./pages/home"
import About from "./pages/about"
import { ClientProvider } from "./components/client-provider"

export default function App() {
  return (
    <BrowserRouter>
      <ClientProvider>
        <nav>
          <Link href="/">Home</Link>
          <Link href="/about">About</Link>
        </nav>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
        </Routes>
      </ClientProvider>
    </BrowserRouter>
  )
}
```

Use it in your root **`main.tsx`** file.
```tsx title="main.tsx"
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import "./index.css";
import App from "./router.tsx";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
```

