## Client Side Routing
React Aria components such as Link, Menu, Tabs, and Table transform elements into clickable links that navigate when clicked. These components utilize the href prop to render as an `<a>` tag, supporting attributes like target and download.
And with Tanstack Router, you'll get the autocomplete which will help you to define the routes typesafely.

### Client Provider
To integrate with Tanstack Start, ensure the locale on the server matches the client, and configure React Aria links to use the Tanstack Router.

```tsx title="client-provider.tsx"
import { type NavigateOptions, type ToOptions, useRouter, } from "@tanstack/react-router";
import { RouterProvider } from "react-aria-components";

declare module "react-aria-components" {
  interface RouterConfig {
    href: ToOptions["to"];
    routerOptions: Omit<NavigateOptions, keyof ToOptions>;
  }
}

export function ClientProvider({ children }: { children: React.ReactNode }) {
  const router = useRouter();

  return (
    <RouterProvider
      navigate={(to, options) => router.navigate({ to, ...options })}
    >
      {children}
    </RouterProvider>
  );
}

```

Then use in your **`__root.tsx`** file.

```tsx title="__root.tsx"
import { ClientProvider } from "#/components/client-provider"

...
function RootDocument({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" suppressHydrationWarning>
      //
      <ClientProvider>
        {children}
      </ClientProvider>
      //
    </html>
  )
}
```

## Dark Mode
### Theme Provider
> If you are using the Tanstack CLI, Theme Provider is already setup. You can skip this step

If the theme-provider isn't setup, or you want to create your own then you have to create one.
<CLI command='install' items={['@tabler/icons-react']} />

```tsx title='components/theme-toggle.tsx'
import { IconDeviceDesktop, IconMoon, IconSun } from "@tabler/icons-react";
import { useEffect, useState } from "react";
import { Button } from "#/components/ui/button";

type ThemeMode = "light" | "dark" | "auto";

function getInitialMode(): ThemeMode {
	if (typeof window === "undefined") {
		return "auto";
	}

	const stored = window.localStorage.getItem("theme");
	if (stored === "light" || stored === "dark" || stored === "auto") {
		return stored;
	}

	return "auto";
}

function applyThemeMode(mode: ThemeMode) {
	const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
	const resolved = mode === "auto" ? (prefersDark ? "dark" : "light") : mode;

	document.documentElement.classList.remove("light", "dark");
	document.documentElement.classList.add(resolved);

	if (mode === "auto") {
		document.documentElement.removeAttribute("data-theme");
	} else {
		document.documentElement.setAttribute("data-theme", mode);
	}

	document.documentElement.style.colorScheme = resolved;
}

export default function ThemeToggle() {
	const [mode, setMode] = useState<ThemeMode>("auto");

	useEffect(() => {
		const initialMode = getInitialMode();
		setMode(initialMode);
		applyThemeMode(initialMode);
	}, []);

	useEffect(() => {
		if (mode !== "auto") {
			return;
		}

		const media = window.matchMedia("(prefers-color-scheme: dark)");
		const onChange = () => applyThemeMode("auto");

		media.addEventListener("change", onChange);
		return () => {
			media.removeEventListener("change", onChange);
		};
	}, [mode]);

	function toggleMode() {
		const nextMode: ThemeMode =
			mode === "light" ? "dark" : mode === "dark" ? "auto" : "light";
		setMode(nextMode);
		applyThemeMode(nextMode);
		window.localStorage.setItem("theme", nextMode);
	}

	return (
		<Button
			aria-label={`Switch to ${mode}` === "light" ? "dark" : "light" + "mode"}
			onPress={toggleMode}
			size="icon"
			variant="outline"
		>
			{mode === "auto" ? (
				<IconDeviceDesktop
					aria-hidden
					className="absolute rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0"
				/>
			) : (
				<>
					<IconSun
						aria-hidden
						className="absolute rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0"
					/>
					<IconMoon
						aria-hidden
						className="absolute rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100"
					/>
				</>
			)}
		</Button>
	);
}
```

## Introduction
React Aria components such as [Link](/docs/components/navigation/link), [Menu](/docs/components/collections/dropdown-menu), [Tabs](/docs/components/navigation/tabs), and [Table](/docs/components/collections/table) transform elements into clickable links that navigate when clicked. These components utilize the `href` prop to render as an `<a>` tag, supporting attributes like `target` and `download`.

User interactions with these links vary by component. For instance, one might use arrow keys to navigate tabs or press enter to open a link within a ComboBox. With the href prop, React Aria facilitates seamless navigation for each component.

Typically, links perform the default browser action when clicked. However, many applications employ client-side routers to prevent full page reloads. The RouterProvider configures React Aria components to integrate with your client-side router. Simply set it up at the root, and any React Aria component with an href will automatically utilize your router.

Note that links to external sites will default to the browser's native navigation, and links not targeting "_self", using the download attribute, or modified with keys like Command or Alt, will also follow the browser's native behavior.

## Router Provider
The `RouterProvider` component accepts two properties: `navigate` and `useHref`. Assign `navigate` to a function from your routing framework that handles client-side navigation. `useHref` is optional and modifies a router-specific href to a standard HTML href, such as by adding a base path. Below are setup examples for various frameworks.

```tsx title="router-provider.tsx" showLineNumbers
import { RouterProvider } from 'react-aria-components';
import { useNavigate } from 'your-router';

export default function Layout() {
  let navigate = useNavigate();

  return (
    <RouterProvider navigate={navigate}>
      {/* ... */}
    </RouterProvider>
  );
}
```

